package com.library.server.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.ApiResult; import com.library.pojo.entity.Category; import com.library.server.service.CategoryService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/categories") @RequireRole({RoleConstant.ADMIN,RoleConstant.READER}) public class CategoryController {private final CategoryService service;public CategoryController(CategoryService service){this.service=service;} @GetMapping public ApiResult<List<Category>> list(){return ApiResult.success(service.list());} @PostMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> save(@RequestBody Category x){service.save(x);return ApiResult.success();} @PutMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> update(@RequestBody Category x){service.update(x);return ApiResult.success();} @DeleteMapping("/{id}") @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> delete(@PathVariable Long id){service.delete(id);return ApiResult.success();}}
